for s in /usr/lib/openssh/sftp-server /usr/libexec/openssh/sftp-server /usr/lib/ssh/sftp-server /usr/libexec/sftp-server; do [ -x "$s" ] && exit 0; done; d=$(command -v sshd) && [ -x "$(dirname "$(readlink -f "$d")")/../libexec/sftp-server" ] && exit 0; export DEBIAN_FRONTEND=noninteractive; apt-get -o DPkg::Lock::Timeout=180 install -y -q --no-install-recommends openssh-sftp-server 2>&1 | tail -n 3; [ -x /usr/lib/openssh/sftp-server ]
